return ['x-generator'=>'GlotPress/4.1.0','translation-revision-date'=>'2026-09-30 01:15:29+0000','plural-forms'=>'nplurals=3; plural=(n % 10 == 1 && n % 100 != 11) ? 0 : ((n % 10 >= 2 && n % 10 <= 4 && (n % 100 < 12 || n % 100 > 14)) ? 1 : 2);','project-id-version'=>'Plugins - Google Analytics for WooCommerce - Stable (latest release)','language'=>'sr_RS','messages'=>['Category: %s'=>'Категорија: %s','Whether a Google Analytics measurement ID is configured.'=>'Да ли је подешен Google Analytics ИБ мерења.','The recognized prefix for the configured measurement ID, or X for an unrecognized prefix.'=>'Препознати префикс подешеног ИБ-а мерења или X за непрепознати префикс.','The configured Google Analytics measurement or tag ID.'=>'Подешени Google Analytics ИБ мерења или ознаке.','Tag: %s'=>'Ознака: %s','Shop'=>'Продавница','Read the current Google Analytics for WooCommerce tracking configuration and enabled event settings.'=>'Прочитајте тренутна подешавања праћења Google Analytics for WooCommerce и подешавања укључених догађаја.','Google Analytics for WooCommerce is not initialized.'=>'Google Analytics for WooCommerce није покренут.','Google Analytics for WooCommerce settings are unavailable.'=>'Подешавања Google Analytics for WooCommerce нису доступна.','Get Google Analytics tracking settings'=>'Добави подешавања Google Analytics праћења','Google Analytics for WooCommerce requires WooCommerce version %1$s or higher.'=>'Google Analytics for WooCommerce захтева WooCommerce издање %1$s или новије.','Google Analytics for WooCommerce requires WooCommerce version %1$s or higher. You are using version %2$s'=>'Google Analytics for WooCommerce захтева WooCommerce издање %1$s или новије. Ви користите издање %2$s','Event Tracking'=>'Праћење догађаја','Product SKU with prefixed (#) ID as fallback'=>'Шифра производа, уз ИБ са префиксом (#) као резервно решење','Product ID'=>'ИБ производа','Product Identification'=>'Препознавање производа','Specify how your products will be identified to Google Analytics. Changing this setting may cause issues with historical data if a product was previously identified using a different structure.'=>'Наведите како ће ваши производи бити препознати у Google Analytics-у. Промена овог подешавања може да изазове проблеме са историјским подацима ако је производ раније препознаван помоћу другачије структуре.','Your website is configured to use Universal Analytics which Google retired in July of 2023. Update your account using the %1$ssetup assistant%2$s and then update your %3$sWooCommerce settings%4$s.'=>'Ваш веб сајт је подешен да користи Universal Analytics, који је Google повукао у јулу 2023. Ажурирајте свој налог помоћу %1$sпомоћника за подешавање%2$s, а затим ажурирајте своја %3$sWooCommerce подешавања%4$s.','The formatted product identifier to use in Google Analytics events.'=>'Обликовани идентификатор производа који се користи у Google Analytics догађајима.','Documentation'=>'Документација','By using this extension, you may be storing personal data or sharing data with an external service. %1$sLearn more about what data is collected by Google and what you may want to include in your privacy policy%2$s.'=>'Коришћењем овог проширења можда чувате личне податке или их делите са спољном услугом. %1$sСазнајте више о томе које податке прикупља Google и шта бисте могли да укључите у своја правила приватности%2$s.','Product List'=>'Списак производа','Search Results'=>'Резултати претраге','5 minutes'=>'5 минута','Provides the integration between WooCommerce and Google Analytics.'=>'Обезбеђује интеграцију између WooCommerce-а и Google Analytics-а.','Set up Google Analytics'=>'Подеси Google Analytics','Enabling this option will allow incoming linker parameters from other websites.'=>'Укључивање ове могућности дозволиће долазне параметре повезивања са других веб сајтова.','Accept Incoming Linker Parameters'=>'Прихвати долазне параметре повезивања','Add a comma separated list of domains for automatic linking. %1$sRead more about Cross Domain Measurement%2$s'=>'Додајте списак домена раздвојених зарезима за аутоматско повезивање. %1$sПрочитајте више о мерењу између домена%2$s','Cross Domain Tracking'=>'Праћење између домена','Log into your Google Analytics account to find your ID. e.g. <code>GT-XXXXX</code> or <code>G-XXXXX</code>'=>'Пријавите се на свој Google Analytics налог да бисте пронашли свој ИБ. нпр. <code>GT-XXXXX</code> или <code>G-XXXXX</code>','Google Analytics Tracking ID'=>'Google Analytics ИБ праћења','Add advanced tracking for your sales funnel, coupons and more. [<a href="%s" target="_blank">Learn more</a> &gt;]'=>'Додајте напредно праћење свог продајног левка, купона и још много тога. [<a href="%s" target="_blank">Сазнајте више</a> &gt;]','Get detailed insights into your sales with Google Analytics Pro'=>'Добијте детаљне увиде у своју продају помоћу Google Analytics Pro','Enable this to find broken or dead links. An "Event" with category "Error" and action "404 Not Found" will be created in Google Analytics for each incoming pageview to a non-existing page. By setting up a "Custom Goal" for these events within Google Analytics you can find out where broken links originated from (the referrer). %1$sRead how to set up a goal%2$s.'=>'Укључите ово да бисте пронашли неисправне или мртве везе. „Догађај“ са категоријом „Error“ и радњом „404 Not Found“ биће направљен у Google Analytics-у за сваки долазни преглед непостојеће странице. Подешавањем „произвољног циља“ за ове догађаје у Google Analytics-у можете да сазнате одакле неисправне везе потичу (упућивач). %1$sПрочитајте како да подесите циљ%2$s.','Track 404 (Not found) Errors'=>'Прати грешке 404 (није пронађено)','Support'=>'Подршка','Settings'=>'Подешавања','https://woocommerce.com'=>'https://woocommerce.com','Please note, for transaction tracking to work properly, you will need to use a payment gateway that redirects the customer back to a WooCommerce order received/thank you page.'=>'Имајте на уму да је за исправно праћење трансакција потребно да користите посредника плаћања који купца враћа на WooCommerce страницу примљене поруџбине/захвалнице.','Please allow Google Analytics 24 hours to start displaying results.'=>'Дајте Google Analytics-у 24 сата да почне да приказује резултате.','Product Clicks from Listing Pages'=>'Притисци на производе са страница списка','Product Detail Views'=>'Прегледи детаља производа','Checkout Process Initiated'=>'Покренут поступак плаћања','Product Impressions from Listing Pages'=>'Прикази производа на страницама списка','Remove from Cart Events'=>'Догађаји уклањања из корпе','Add to Cart Events'=>'Догађаји додавања у корпу','This requires a payment gateway that redirects to the thank you/order received page after payment. Orders paid with gateways which do not do this will not be tracked.'=>'Ово захтева посредника плаћања који након плаћања преусмерава на страницу захвалнице/примљене поруџбине. Поруџбине плаћене преко посредника који то не раде неће бити праћене.','Purchase Transactions'=>'Трансакције куповине','Set the Google Analytics code to support Display Advertising. %1$sRead more about Display Advertising%2$s.'=>'Подесите Google Analytics кôд за подршку приказном оглашавању. %1$sПрочитајте више о приказном оглашавању%2$s.','"Display Advertising" Support'=>'Подршка за „приказно оглашавање“','Google Analytics for WooCommerce'=>'Google Analytics for WooCommerce','https://wordpress.org/plugins/woocommerce-google-analytics-integration/'=>'https://wordpress.org/plugins/woocommerce-google-analytics-integration/','Google Analytics is a free service offered by Google that generates detailed statistics about the visitors to a website.'=>'Google Analytics је бесплатна услуга коју нуди Google и која генерише детаљну статистику о посетиоцима веб сајта.','Allows Google Analytics tracking code to be inserted into WooCommerce store pages.'=>'Омогућава убацивање Google Analytics кода за праћење у странице WooCommerce продавнице.','WooCommerce'=>'WooCommerce','Google Analytics'=>'Google Analytics']];